            'commercial': 'Non-compliance. A purely commercial defense does not engage with autonomy or transparency dimensions.'
        }
    };

    class MindMarketAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'MindMarket: Neuromarketing & Decision Neuroscience';
            this.version = '1.1.0';
        }

        _t(key, params) {
            return (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(key, params) : key;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    totalScore: 0,
                    dqsTotal: 0,
                    calibrationTotal: 0,
                    ethicsScore: 0,
                    overFitScore: 0,
                    launchSuccess: 0,
                    roundScores: [],
                    calibrationScores: [],
                    dqsHistory: [],
                    totalHistory: [],
                    confidenceHistory: [],
                    qualityHistory: [],
                    ethicsSubmitted: false,
                    randomEventApplied: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    mainChoice: '',
                    secondChoice: '',
                    ethicsChoice: '',
                    overfitChoice: '',
                    confidence: 'medium'
                };
            }
            this._updateBriefing(state);
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, ROUNDS.length - 1);
            var round = ROUNDS[idx];
            var isEs = ((window.mySimulation && window.mySimulation.lang) || 'en') === 'es';

            var titleEl = document.getElementById('briefingTitle');
            var textEl = document.getElementById('briefingText');
            var dataEl = document.getElementById('dataContent');
            var dynEl = document.getElementById('dynamicControls');

            if (titleEl) titleEl.textContent = (isEs && round.titleEs) ? round.titleEs : round.title;
            if (textEl) textEl.innerHTML = (isEs && round.briefingEs) ? round.briefingEs : round.briefing;
            if (dataEl) dataEl.innerHTML = (isEs && round.dataHtmlEs) ? round.dataHtmlEs : round.dataHtml;

            if (!dynEl) return;

            var period = state.currentPeriod || 1;
            var html = '';
            var t = this._t.bind(this);

            if (period === 1) {
                html += '<label for="mainChoiceInput" data-i18n="r1_creative_label">Primary Creative Selection</label>';
                html += '<select id="mainChoiceInput" class="form-control">';
                html += '<option value="">' + t('ph_select_creative') + '</option>';
                html += '<option value="C-1">' + t('opt_c1') + '</option>';
                html += '<option value="C-2">' + t('opt_c2') + '</option>';
                html += '<option value="C-3">' + t('opt_c3') + '</option>';
                html += '<option value="C-4">' + t('opt_c4') + '</option>';
                html += '<option value="C-5">' + t('opt_c5') + '</option>';
                html += '</select>';
            } else if (period === 2) {
                html += '<label for="mainChoiceInput" data-i18n="r2_frame_label">Pricing Frame Selection</label>';
                html += '<select id="mainChoiceInput" class="form-control">';
                html += '<option value="">' + t('ph_select_frame') + '</option>';
                html += '<option value="P-1">' + t('opt_p1') + '</option>';
                html += '<option value="P-2">' + t('opt_p2') + '</option>';
                html += '<option value="P-3">' + t('opt_p3') + '</option>';
                html += '<option value="P-4">' + t('opt_p4') + '</option>';
                html += '<option value="P-5">' + t('opt_p5') + '</option>';
                html += '<option value="P-6">' + t('opt_p6') + '</option>';
                html += '<option value="P-7">' + t('opt_p7') + '</option>';
                html += '<option value="P-8">' + t('opt_p8') + '</option>';
                html += '<option value="P-9">' + t('opt_p9') + '</option>';
                html += '</select>';
            } else if (period === 3) {
                html += '<label for="mainChoiceInput" data-i18n="r3_shelf_label">Shelf Configuration</label>';
                html += '<select id="mainChoiceInput" class="form-control">';
                html += '<option value="">' + t('ph_select_config') + '</option>';
                html += '<option value="A">' + t('opt_shelf_a') + '</option>';
                html += '<option value="B">' + t('opt_shelf_b') + '</option>';
                html += '<option value="C">' + t('opt_shelf_c') + '</option>';
                html += '</select>';

                html += '<label for="secondChoiceInput" data-i18n="r3_ux_label">Digital UX Variant</label>';
                html += '<select id="secondChoiceInput" class="form-control">';
                html += '<option value="">' + t('ph_select_ux') + '</option>';
                html += '<option value="V-1">' + t('opt_ux_v1') + '</option>';
                html += '<option value="V-2">' + t('opt_ux_v2') + '</option>';
