                html += '<label for="ethicsChoiceInput" data-i18n="r3_ethics_label">Ethical Checkpoint Response</label>';
                html += '<select id="ethicsChoiceInput" class="form-control">';
                html += '<option value="">' + t('ph_select_ethics') + '</option>';
                html += '<option value="principled">' + t('opt_ethics_principled') + '</option>';
                html += '<option value="generic">' + t('opt_ethics_generic') + '</option>';
                html += '<option value="commercial">' + t('opt_ethics_commercial') + '</option>';
                html += '</select>';
            } else if (period === 4) {
                html += '<label for="mainChoiceInput" data-i18n="r4_schedule_label">Reward Schedule Architecture</label>';
                html += '<select id="mainChoiceInput" class="form-control">';
                html += '<option value="">' + t('ph_select_schedule') + '</option>';
                html += '<option value="fixed">' + t('opt_sched_fixed') + '</option>';
                html += '<option value="variable">' + t('opt_sched_variable') + '</option>';
                html += '<option value="progressive">' + t('opt_sched_progressive') + '</option>';
