                html += '</select>';

                html += '<label for="overfitChoiceInput" data-i18n="r4_overfit_label">Anti-Over-Fit Defense: Which neuro signal did you most likely over-weight?</label>';
                html += '<select id="overfitChoiceInput" class="form-control">';
                html += '<option value="">' + t('ph_select_signal') + '</option>';
                html += '<option value="gsr_arousal">' + t('opt_of_gsr') + '</option>';
                html += '<option value="eeg_aai">' + t('opt_of_eeg') + '</option>';
                html += '<option value="eye_fixation">' + t('opt_of_eye') + '</option>';
                html += '<option value="iat_association">' + t('opt_of_iat') + '</option>';
                html += '<option value="survey_data">' + t('opt_of_survey') + '</option>';
                html += '</select>';
            }

            dynEl.innerHTML = html;
            // re-apply translations to the labels just injected: applyTranslations only runs once
            // at boot, and _updateBriefing regenerates this markup on every round change
            if (window.mySimulation && window.mySimulation.applyTranslations) { window.mySimulation.applyTranslations(); }
        }

        validateDecisions(decisions) {
            var st = window.mySimulation.state;
            var period = st.currentPeriod || 1;

            var mainEl = document.getElementById('mainChoiceInput');
            var secondEl = document.getElementById('secondChoiceInput');
            var ethicsEl = document.getElementById('ethicsChoiceInput');
            var overfitEl = document.getElementById('overfitChoiceInput');
            var confEl = document.getElementById('confidenceInput');

            if (mainEl) decisions.mainChoice = mainEl.value;
            if (secondEl) decisions.secondChoice = secondEl.value;
            if (ethicsEl) decisions.ethicsChoice = ethicsEl.value;
            if (overfitEl) decisions.overfitChoice = overfitEl.value;
            if (confEl) decisions.confidence = confEl.value;

            if (!decisions.mainChoice) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('select_warning'), 'warning'
                );
                return false;
            }

            if (period === 3 && (!decisions.secondChoice || !decisions.ethicsChoice)) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('all_fields_warning'), 'warning'
                );
                return false;
            }

            if (period === 4 && !decisions.overfitChoice) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('overfit_warning'), 'warning'
                );
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;

            var decisionQuality = 0;
            var calibrationScore = 0;
            var ethicsPoints = 0;
            var overfitPoints = 0;
            var feedbackMsg = '';
            var roundLabel = '';

            if (period === 1) {
                roundLabel = 'rl_ad_creative';
                decisionQuality = ANSWER_KEY.r1[d.mainChoice] || 1;
                feedbackMsg = FEEDBACK.r1[d.mainChoice] ? this._t('fb_r1_' + d.mainChoice) : this._t('fb_default');
            } else if (period === 2) {
                roundLabel = 'rl_pricing_frame';
                decisionQuality = ANSWER_KEY.r2[d.mainChoice] || 1;
                feedbackMsg = FEEDBACK.r2[d.mainChoice] ? this._t('fb_r2_' + d.mainChoice) : this._t('fb_default');
            } else if (period === 3) {
                roundLabel = 'rl_store_ux_ethics';
                var shelfScore = ANSWER_KEY.r3shelf[d.mainChoice] || 1;
                var uxScore = ANSWER_KEY.r3ux[d.secondChoice] || 1;
                decisionQuality = (shelfScore + uxScore) / 2;
                ethicsPoints = ANSWER_KEY.r3ethics[d.ethicsChoice] || 0;
                ds.ethicsScore = ethicsPoints;
                ds.ethicsSubmitted = true;
                feedbackMsg = this._t('fb_prefix_shelf') + this._t(d.mainChoice === 'B' ? 'fb_shelf_b' : d.mainChoice === 'C' ? 'fb_shelf_c' : 'fb_shelf_default');
                feedbackMsg += '<br><br>' + this._t('fb_prefix_ux') + this._t(d.secondChoice === 'V-2' ? 'fb_ux_v2' : d.secondChoice === 'V-4' ? 'fb_ux_v4' : d.secondChoice === 'V-1' ? 'fb_ux_v1' : 'fb_ux_default');
                feedbackMsg += '<br><br>' + this._t('fb_prefix_ethics') + (FEEDBACK.r3ethics[d.ethicsChoice] ? this._t('fb_ethics_' + d.ethicsChoice) : '');
            } else if (period === 4) {
                roundLabel = 'rl_loyalty_overfit';
                var scheduleScore = ANSWER_KEY.r4schedule[d.mainChoice] || 1;
                overfitPoints = ANSWER_KEY.r4overfit[d.overfitChoice] || 1;
                decisionQuality = scheduleScore;
                ds.overFitScore = overfitPoints;
                feedbackMsg = this._t(d.mainChoice === 'variable' ? 'fb_sched_variable' : d.mainChoice === 'social' ? 'fb_sched_social' : d.mainChoice === 'progressive' ? 'fb_sched_progressive' : 'fb_sched_default');
                feedbackMsg += '<br><br>' + this._t('fb_prefix_overfit') + this._t(d.overfitChoice === 'gsr_arousal' ? 'fb_of_gsr' : d.overfitChoice === 'eeg_aai' ? 'fb_of_eeg' : d.overfitChoice === 'eye_fixation' ? 'fb_of_eye' : d.overfitChoice === 'iat_association' ? 'fb_of_iat' : 'fb_of_default');
            }

            var confLevel = d.confidence;
            var qualityNorm = decisionQuality / 5;
            if (confLevel === 'high' && qualityNorm < 0.5) {
                calibrationScore = -1.5;
            } else if (confLevel === 'high' && qualityNorm >= 0.7) {
                calibrationScore = 2;
            } else if (confLevel === 'medium') {
                calibrationScore = 1;
            } else if (confLevel === 'low' && qualityNorm >= 0.7) {
                calibrationScore = 0.5;
            } else if (confLevel === 'low' && qualityNorm < 0.5) {
                calibrationScore = 1;
            } else {
                calibrationScore = 0.5;
            }

            var dqsWeighted = decisionQuality * 7;
            // Do NOT clamp to 0: clamping muted the overconfidence penalty (calibrationScore -1.5)
            // and made the live Calibration KPI card (bound to calibrationTotal) contradict both the
            // history table and the debrief, which report the raw negative calibration and declare
            // "over-confidence detected." The penalty is now real and consistent across card/table/
            // summary; launchSuccess is floored below so the composite stays in [0,100]. (fix v1.1.0)
            var calWeighted = calibrationScore * 5;
            var ethWeighted = ethicsPoints * 7.5;
            var ofWeighted = overfitPoints * 1;
            var roundTotal = dqsWeighted + calWeighted + ethWeighted + ofWeighted;

            ds.dqsTotal += dqsWeighted;
            ds.calibrationTotal += calWeighted;
            ds.totalScore += roundTotal;

            ds.roundScores.push(roundTotal);
            ds.dqsHistory.push(Math.round(ds.dqsTotal * 10) / 10);
            ds.totalHistory.push(Math.round(ds.totalScore * 10) / 10);
            ds.confidenceHistory.push(confLevel === 'high' ? 3 : confLevel === 'medium' ? 2 : 1);
            ds.qualityHistory.push(decisionQuality);
            ds.calibrationScores.push(calibrationScore);

            // platform score: same launch-success formula used for the round 4 debrief metric,
            // recomputed every round from the running accumulators (already 0-100, clamp only)
            var dqsPctNow = (ds.dqsTotal / 140) * 35;
            var calPctNow = (ds.calibrationTotal / 40) * 10;
            var ethPctNow = (ds.ethicsScore / 2) * 15;
            var ofPctNow = (ds.overFitScore / 5) * 5;
            var mosPctNow = (ds.totalScore / 200) * 10;
            var overallScore = Math.max(0, Math.min(100, Math.round((dqsPctNow + calPctNow + ethPctNow + ofPctNow + mosPctNow) * 1.33)));
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScore });

            if (period === 4) {
                var dqsPct = (ds.dqsTotal / 140) * 35;
                var calPct = (ds.calibrationTotal / 40) * 10;
                var ethPct = (ds.ethicsScore / 2) * 15;
                var ofPct = (ds.overFitScore / 5) * 5;
                var mosPct = (ds.totalScore / 200) * 10;
                ds.launchSuccess = Math.round(Math.max(0, Math.min(100, (dqsPct + calPct + ethPct + ofPct + mosPct) * 1.33)));
            }

            var feedPanel = document.getElementById('feedbackPanel');
            var feedTitle = document.getElementById('feedbackTitle');
            var feedContent = document.getElementById('feedbackContent');
            if (feedPanel) {
                feedPanel.style.display = 'block';
                if (feedTitle) feedTitle.textContent = this._t(roundLabel) + this._t('fb_analysis_suffix');
                if (feedContent) feedContent.innerHTML = feedbackMsg;
            }

            var self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext });
            })(state.currentPeriod + 1), 500);

            return {
                period: period,
                roundLabel: roundLabel,
                mainChoice: d.mainChoice,
                secondChoice: d.secondChoice || '--',
                confidence: d.confidence,
                decisionQuality: Math.round(decisionQuality * 10) / 10,
                calibration: Math.round(calibrationScore * 10) / 10,
                ethicsPoints: ethicsPoints,
                roundTotal: Math.round(roundTotal * 10) / 10,
                cumulativeScore: Math.round(ds.totalScore * 10) / 10
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('totalScoreDisplay', 'domainState.totalScore', function(v) { return Math.round(v); });
            uiManager.bind('dqsDisplay', 'domainState.dqsTotal', function(v) { return Math.round(v); });
            uiManager.bind('calibrationDisplay', 'domainState.calibrationTotal', function(v) { return v > 0 ? '+' + Math.round(v) : Math.round(v); });
            uiManager.bind('ethicsDisplay', 'domainState.ethicsScore', function(v) { return v + '/2'; });
            uiManager.bind('lssDisplay', 'domainState.launchSuccess', function(v) { return v > 0 ? v + '%' : '--'; });
