        getChartData(state) {
            var ds = state.domainState;
            var labels = ds.roundScores.map(function(_, i) { return 'R' + (i + 1); });
            return {
                scoreChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.qualityHistory.map(function(v) { return v * 7; }) },
                        { data: ds.roundScores }
                    ]
