        getPerformanceSummary(history) {
            if (!history || history.length === 0) return {};

            var last = history[history.length - 1];
            var ds = window.mySimulation.state.domainState;
            var totalScore = ds.totalScore;
            var lss = ds.launchSuccess;

            // performance and insights are translation keys, not literal text: the Open player's
            // overlay renderer looks up any lowercase_underscore value through t() automatically
            var performance = 'perf_developing';
            if (lss >= 80) performance = 'perf_excellent';
            else if (lss >= 60) performance = 'perf_good';
            else if (lss >= 40) performance = 'perf_moderate';

            var insights = [];
            if (lss >= 75) {
                insights.push('insight_literacy');
            }
            if (ds.ethicsScore === 2) {
                insights.push('insight_ethics_full');
            } else if (ds.ethicsScore < 2) {
                insights.push('insight_ethics_gap');
            }

            var calTotal = ds.calibrationScores.reduce(function(a, b) { return a + b; }, 0);
            if (calTotal > 4) {
                insights.push('insight_calibration_good');
            } else if (calTotal < 0) {
                insights.push('insight_overconfidence');
            }

            if (ds.overFitScore >= 4) {
                insights.push('insight_overfit_strong');
            }

            return {
                totalScore: Math.round(totalScore),
                launchSuccess: lss,
                performance: performance,
                insights: insights,
                ethicsScore: ds.ethicsScore + '/2',
                overFitDefense: ds.overFitScore + '/5'
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.decisionQuality <= 2 && results.confidence === 'high') {
                return window.mySimulation.t('hint_overconfident');
            }
            if (results.decisionQuality >= 4) {
                return window.mySimulation.t('hint_strong');
            }
            if (results.ethicsPoints === 0 && state.currentPeriod === 3) {
                return window.mySimulation.t('hint_ethics');
            }
            return null;
        }

